begin;insert into public.security_permissions(codigo,modulo,nome,criticidade)values('bank.remittance.read','integracoes','Consultar remessas','sensivel'),('bank.remittance.manage','integracoes','Gerar remessas CNAB','critica')on conflict(codigo)do update set nome=excluded.nome;insert into public.security_role_permissions(role_id,permission_id)select r.id,p.id from public.security_roles r join public.security_permissions p on p.codigo in('bank.remittance.read','bank.remittance.manage')where r.codigo='tenant_admin'on conflict do nothing;create table public.payroll_bank_accounts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),employment_link_id uuid not null references public.employment_links(id),bank_code char(3)not null,branch text not null,account_number text not null,account_digit text,account_type text not null,holder_document text not null,active boolean default true,unique(tenant_id,employment_link_id,bank_code,branch,account_number));create table public.bank_remittance_batches(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),payroll_cycle_id uuid not null references public.payroll_cycles(id),bank_code char(3)not null,layout_version text not null,status text not null default'gerado',records_count int not null,total_amount numeric(18,2)not null,file_content text not null,file_sha256 text not null,created_by uuid references public.profiles(id),created_at timestamptz default now(),check(status in('gerado','validado','enviado','aceito','rejeitado')),check(file_sha256~'^[0-9a-f]{64}$'),unique(payroll_cycle_id,bank_code,layout_version));alter table public.payroll_bank_accounts enable row level security;alter table public.bank_remittance_batches enable row level security;do $$begin if to_regnamespace('auth')is not null then create policy bank_accounts on public.payroll_bank_accounts for all to authenticated using(private.has_tenant_permission(tenant_id,'bank.remittance.read'))with check(private.has_tenant_permission(tenant_id,'bank.remittance.manage'));create policy bank_batches on public.bank_remittance_batches for all to authenticated using(private.has_tenant_permission(tenant_id,'bank.remittance.read'))with check(private.has_tenant_permission(tenant_id,'bank.remittance.manage'));end if;end$$;revoke all on public.payroll_bank_accounts,public.bank_remittance_batches from anon;do $$begin if exists(select 1 from pg_roles where rolname='authenticated')then grant select,insert,update on public.payroll_bank_accounts,public.bank_remittance_batches to authenticated;end if;end$$;commit;
